async function fetchTechStackPages(): Promise<TechStackPage[]> {
  const supabase = createPublicClient();
  const { data: services } = await supabase.from('services').select('id, slug');
  const serviceSlugById: Record<string, string> = Object.fromEntries((services ?? []).map((s) => [s.id, s.slug]));

  const { data, error } = await supabase
    .from('tech_stack_pages')
    .select('*')
    .eq('is_active', true)
    .order('sort_order', { ascending: true });

  if (error || !data || data.length === 0) {
    if (error) console.error(`[getTechStackPages] failed: ${error.message} (code ${error.code})`);
    return SAMPLE_TECH_STACK_PAGES;
  }

  return data
    .filter((row) => serviceSlugById[row.service_id])
    .map((row) => ({
      serviceSlug: serviceSlugById[row.service_id],
      capabilityLabel: row.capability_label,
      slug: row.slug,
      title: row.title,
      tagline: row.tagline,
      overview: row.overview,
      overviewExtra: row.overview_extra,
      implementation: row.implementation ?? [],
      benefits: row.benefits ?? [],
      companies: row.companies ?? [],
      useCases: row.use_cases ?? [],
      faqs: row.faqs ?? [],
      primaryTech: row.primary_tech ?? [],
      seoTitle: row.seo_title ?? null,
      seoDescription: row.seo_description ?? null,
      targetKeywords: row.target_keywords ?? [],
    }));
}

export const getTechStackPages = unstable_cache(fetchTechStackPages, ['tech-stack-pages'], {
  tags: ['tech-stack-pages'],
  revalidate: 60,
});

export async function findTechStackPage(serviceSlug: string, slug: string): Promise<TechStackPage | null> {
  const pages = await getTechStackPages();
  return pages.find((p) => p.serviceSlug === serviceSlug && p.slug === slug) ?? null;
}

/** Capability label -> deep-dive slug for one service, built in one fetch so a capability-card grid can look up every card without N calls. */
export async function techStackSlugMapForService(serviceSlug: string): Promise<Record<string, string>> {
  const pages = await getTechStackPages();
  return Object.fromEntries(
    pages.filter((p) => p.serviceSlug === serviceSlug).map((p) => [p.capabilityLabel, p.slug])
  );
}

export async function techStackPagesForService(serviceSlug: string): Promise<TechStackPage[]> {
  const pages = await getTechStackPages();
  return pages.filter((p) => p.serviceSlug === serviceSlug);
}

export async function getAllTechStackParams(): Promise<{ serviceSlug: string; slug: string }[]> {
  const pages = await getTechStackPages();
  return pages.map((p) => ({ serviceSlug: p.serviceSlug, slug: p.slug }));
}
